module bank_account;

struct Account { balance: Int }

enum Op {
    Deposit { amount: Int },
    Withdraw { amount: Int }
}

/// Applies a single operation to an account, returning the new account state.
fn apply(in acc: Account, in op: Op) -> Account {
    match op {
        Op::Deposit { amount } => {
            Account { balance: acc.balance + amount }
        }
        Op::Withdraw { amount } => {
            if acc.balance >= amount {
                Account { balance: acc.balance - amount }
            } else {
                acc // Insufficient funds, return unchanged account
            }
        }
    }
}

/// Runs a sequence of operations on an account starting from zero balance,
/// and returns the final balance.
fn run(in ops: [Op; 4]) -> Int {
    let initial_account = Account { balance: 0 };
    var current_account = initial_account;

    for op in ops {
        current_account = apply(current_account, op);
    }

    current_account.balance
}

spec run {
    then run([
        Op::Deposit { amount: 100 },
        Op::Deposit { amount: 50 },
        Op::Withdraw { amount: 30 },
        Op::Withdraw { amount: 20 }
    ]) == 100 + 50 - 30 - 20; // Expected: 100
}

spec run_insufficient_funds {
    then run([
        Op::Deposit { amount: 10 },
        Op::Withdraw { amount: 20 }, // Should fail, balance remains 10
        Op::Deposit { amount: 5 },
        Op::Withdraw { amount: 15 }  // Should fail, balance remains 15
    ]) == 15;
}

fn main() -> Int {
    // Example usage: Start at 0, deposit 100, withdraw 30, deposit 5, withdraw 15
    // Expected: 100 - 30 + 5 = 75
    let ops: [Op; 4] = [
        Op::Deposit { amount: 100 },
        Op::Withdraw { amount: 30 },
        Op::Deposit { amount: 5 },
        Op::Withdraw { amount: 15 }
    ];
    run(ops)
}

