// Define the Node structure. Since we are using Box, we must define it
// recursively, which is fine as long as we use Box.
struct Node {
    value: Int,
    next: Option[Box[Node]]
}

/// Builds a singly linked list: a -> b -> c
fn list3(take a: Int, take b: Int, take c: Int) -> Node {
    // Create the last node (c)
    let node_c = Node { value: c, next: None };

    // Create the middle node (b) pointing to c
    let node_b = Node { value: b, next: Some { value: c, next: None } };

    // Create the first node (a) pointing to b
    Node { value: a, next: Some { value: b, next: Some { value: c, next: None } } }
}

/// Returns the sum of every value in the list.
fn sum_list(in n: Node) -> Int {
    let mut current = n;
    let mut sum = 0;

    // We must traverse by consuming the 'next' pointer, which requires
    // careful handling of ownership.
    loop {
        sum = sum + current.value;

        // Check if there is a next node
        match current.next {
            None => break,
            Some(next_box) => {
                // To continue iteration, we must take ownership of the next node
                // and then reconstruct the current node to point to it,
                // or, more simply for this pattern, we pass ownership down
                // and only keep the value for the current step.
                // Since we cannot easily mutate 'current' to point to the next
                // while keeping the original structure intact for the return,
                // we will use recursion which naturally handles ownership transfer.

                // Resetting the loop structure to use recursion for clean ownership transfer.
                break;
            }
        }
    }

    // Recursive implementation is cleaner for consuming structures like this.
    fn recursive_sum(in node: Node) -> Int {
        let mut sum = node.value;
        if let Some(next_box) = node.next {
            sum = sum + recursive_sum(next_box);
        }
        sum
    }

    recursive_sum(n)
}

/// Returns the number of nodes in the list.
fn length(in n: Node) -> Int {
    // Recursive implementation for length counting.
    fn recursive_length(in node: Node) -> Int {
        let mut count = 1;
        if let Some(next_box) = node.next {
            count = count + recursive_length(next_box);
        }
        count
    }

    recursive_length(n)
}

