        // To test a single node, we must construct it manually since list3 always makes 3.
        let single_node = Node { value: 10, next: None };
        sum_list(single_node) == 10;
        length(single_node) == 1;
    }

    // Test case: Empty list (conceptually, though list3 forces 3 nodes)
    // We test the base case of the recursion by constructing a known empty-next node.
    then {
        let empty_next_node = Node { value: 5, next: None };
        sum_list(empty_next_node) == 5;
        length(empty_next_node) == 1;
    }
}

fn main() -> Int {
    // Example usage: 1 -> 2 -> 3
    let list = list3(1, 2, 3);

