/// Shifts every lowercase ASCII letter in s forward by k positions, wrapping z to a.
/// Every other byte is copied unchanged.
pub fn caesar(in s: Str, take k: Int) -> String {
    let bytes = std::str::split(in s, " "); // Use split to get individual characters/bytes if needed, but since we are dealing with ASCII range, direct byte iteration is better.

    // Since we are dealing with ASCII bytes and the requirement is "Every other byte is copied unchanged",
    // we should process the string byte by byte, checking the index parity.

    let mut result_builder = std::str::builder();
    let s_bytes = std::str::bytes_of_str(in s);

    for i in 0..std::array::len(s_bytes) {
        let byte = std::array::select(s_bytes, i);

        // Check if the index is even (0, 2, 4, ...)
        if i % 2 == 0 {
            // This byte is at an even index, it must be copied unchanged.
            // Since we are iterating over bytes, we treat the byte value as the character.
            // We need to convert the byte value back to a String piece.
            let char_str = std::str::to_string(byte);
            std::str::push(mut result_builder, char_str);
        } else {
            // This byte is at an odd index, check if it's a lowercase letter.
            let byte_val = byte;

            // Check if it's in the range 'a' (97) to 'z' (122)
            if byte_val >= 97 && byte_val <= 122 {
                // Calculate the shifted position: (original_pos - 'a' + k) % 26
                let original_pos = byte_val - 97;

                // Since k is guaranteed 0 <= k < 26, we don't need to worry about k being too large,
                // but we must handle the modulo arithmetic correctly for wrapping.
                let shifted_pos = (original_pos + k) % 26;

                // Calculate the new ASCII value: 'a' + shifted_pos
                let new_byte_val = 97 + shifted_pos;

                // Append the new character
                let new_char_str = std::str::to_string(new_byte_val);
                std::str::push(mut result_builder, new_char_str);
            } else {
                // Not a lowercase letter, copy unchanged.
                let char_str = std::str::to_string(byte);
                std::str::push(mut result_builder, char_str);
            }
        }
    }

    std::str::join(std::array::filled(1, std::str::builder()), std::str::to_string(std::str::builder())) // Placeholder to satisfy return type, actual return is result_builder.to_string()
    // Correct return:
    result_builder.to_string()
}

