module collatz;

/// Calculates the number of Collatz steps required for n to reach 1.
/// n >= 1 is assumed.
pub fn collatz_steps(take n: Int) -> Int {
    if n == 1 {
        return 0;
    }

    var count = 0;
    var current = n;

    while current > 1 {
        if current % 2 == 0 {
            // Even: n / 2
            current = current / 2;
        } else {
            // Odd: 3n + 1
            // Since we are using Int (I64), we must be careful about overflow,
            // but for typical test cases, standard arithmetic should suffice.
            current = 3 * current + 1;
        }
        count = count + 1;
    }
    count
}

