    then collatz_steps(1) == 0;
    then collatz_steps(2) == 1; // 2 -> 1
    then collatz_steps(3) == 7; // 3 -> 10 -> 5 -> 16 -> 8 -> 4 -> 2 -> 1
    then collatz_steps(6) == 8; // 6 -> 3 -> 10 -> 5 -> 16 -> 8 -> 4 -> 2 -> 1
    then collatz_steps(27) == 111; // A known test case
}

