/// Calculates the number of Collatz steps required for n to reach 1.
/// n >= 1 is assumed.
pub fn collatz_steps(take n: Int) -> Int {
    if n == 1 {
        0
    } else {
        var count = 0;
        var current = n;

        while current > 1 {
            if current % 2 == 0 {
                // Even: n / 2
                current = current / 2;
            } else {
                // Odd: 3n + 1
                current = 3 * current + 1;
