module digits_utils;

import std::collections;
import std::io;
import std::array;

/// Returns the decimal digits of n (n >= 0) most significant first.
pub fn digits(take n: Int) -> Array[Int] {
    if n == 0 {
        return std::collections::singleton(0);
    }

    var digits_array: Array[Int] = std::collections::empty();
    var temp_n = n;

    while temp_n > 0 {
        var remainder = temp_n % 10;
        // std::collections::insert_ascending is used to append the least significant digit
        // to the end of the array, which is correct for building the array in reverse order
        // of processing, but since we want MSB first, we must prepend or reverse later.
        // The original logic was flawed because insert_ascending assumes sorted input
        // and appends, which is wrong for building digits.
        // We will collect them and then reverse.
        digits_array = std::collections::concat(digits_array, std::collections::singleton(remainder));
        temp_n = temp_n / 10;
    }
    // The digits were collected LSB first, so we must reverse them.
    std::collections::reversed(digits_array)
}

/// Returns a new array with the elements in reverse order.
pub fn reversed(in xs: Array[Int]) -> Array[Int] {
    std::collections::reversed(in xs)
}

spec digits {
    then digits(0) == std::collections::singleton(0);
    then digits(123) == std::collections::of3(1, 2, 3);
    then digits(9) == std::collections::singleton(9);
    then digits(1000) == std::collections::of4(1, 0, 0, 0);
}

spec reversed {
    then reversed(std::collections::of3(1, 2, 3)) == std::collections::of3(3, 2, 1);
    then reversed(std::collections::singleton(5)) == std::collections::singleton(5);
    then reversed(std::collections::empty()) == std::collections::empty();
}

fn main() -> Int {
    let num1 = 12345;
    let digits1 = digits(num1);
    std::io::println(format!("Digits of {}: {:?}", num1, digits1)).unwrap();

    let num2 = 9001;
    let digits2 = digits(num2);
    std::io::println(format!("Digits of {}: {:?}", num2, digits2)).unwrap();

    let test_array: Array[Int] = std::collections::of4(10, 20, 30, 40);
    let reversed_array = reversed(test_array);
    std::io::println!("Reversed array: {:?}", reversed_array).unwrap();

    0
}

