module fib_loop;

/// Computes the n-th Fibonacci number iteratively.
pub fn fib(take n: Int) -> Int {
    if n < 0 {
        // For simplicity, we treat negative input as an error case,
        // though the prompt implies non-negative input.
        // Since we must return Int, we return 0 for negative n.
        return 0;
    }
    if n == 0 {
        return 0;
    }
    if n == 1 {
        return 1;
    }

    // We need to calculate F(n) using F(n-1) and F(n-2).
    // Initialize: a = F(0) = 0, b = F(1) = 1
    var a: Int = 0;
    var b: Int = 1;
    var result: Int = 0;

    // We start the loop from i=2 up to n.
    var i = 2;
    while i <= n {
        // F(i) = F(i-1) + F(i-2)
        // New result is the sum of the previous two (a and b)
        result = a + b;

        // Shift for the next iteration:
        // The old F(i-1) (which was b) becomes the new F(i-2) (new a)
        a = b;
        // The new result (F(i)) becomes the new F(i-1) (new b)
        b = result;

        i = i + 1;
    }

    // If n >= 2, the final result is stored in 'result' (which is 'b' after the last iteration).
    // If n=2, loop runs once: result=1, a=1, b=1. Returns 1. Correct.
    // If n=3, loop runs twice:
    // i=2: result=1, a=1, b=1
    // i=3: result=2, a=1, b=2. Returns 2. Correct.
    // If n=4, loop runs thrice:
    // i=2: result=1, a=1, b=1
    // i=3: result=2, a=1, b=2
    // i=4: result=3, a=2, b=3. Returns 3. Correct.

    // The final value of 'result' holds F(n) if n >= 2.
    // If n=0 or n=1, we returned early.
    return result;
}

