    then fib(0) == 0;
    then fib(1) == 1;
    then fib(2) == 1;
    then fib(3) == 2;
    then fib(4) == 3;
    then fib(5) == 5;
    then fib(10) == 55;
}

fn main() -> Int {
    // Test with a known value, e.g., F(10) = 55
    fib(10)
}

