pub fn int_sqrt(take n: Int) -> Int {
    if n < 0 {
        // Behavior for negative input is undefined by the prompt,
        // but since we must return Int, we return 0 or panic.
        // Given the constraint "for n >= 0", we assume valid input or handle it safely.
        return 0;
    }

    // Binary search for the square root in the range [0, n].
    // The square root cannot exceed n itself (unless n=0, where sqrt=0).
    // A tighter upper bound is min(n, 2^31 - 1) if we assume 32-bit Int,
    // but since Int is I64, n is a safe upper bound for the search space,
    // although we can use n+1 as the exclusive upper bound.

    var low = 0;
    // The largest possible square root is n itself (if n=0 or n=1).
    // A safe upper bound for the search space is n+1, as we search up to high-1.
    var high = n + 1; 
    var result = 0;

    while low < high {
        // Calculate mid = low + (high - low) / 2 to prevent overflow,
        // although with Int=I64, this is unlikely unless low/high are near I64::MAX.
        var mid = low + (high - low) / 2;

        // Check for potential overflow when calculating mid * mid.
        // Since n is Int (I64), if mid > 0 and mid > I64::MAX / mid, it overflows.
        // If mid > 0 and mid > 3037000499 (approx sqrt(I64::MAX)), it overflows.
        // Since we are searching up to n, and n is Int, if mid*mid overflows,
        // it means mid*mid > I64::MAX, which is certainly > n (unless n=I64::MAX).
