        var mid_sq: Int;
        let overflow_check = if mid == 0 {
            0
        } else if n / mid < mid {
            // mid * mid > n, and potentially overflows Int if n is near I64::MAX
            // But since we only care if it's > n, we can treat it as "too big".
            // We use a sentinel value larger than any possible n.
