module rpn_calculator;

enum Token {
    Num { value: Int },
    Add,
    Sub,
    Mul
}

/// Evaluates a sequence of RPN tokens.
/// The stack is managed internally using a growable Array[Int].
fn eval_rpn(in tokens: [Token; 7]) -> Int {
    var stack: Array[Int] = std::array::empty();

    for token in tokens {
        match token {
            Token::Num { value } => {
                // Push the number onto the stack
                stack = std::array::append(stack, [value]);
            }
            Token::Add => {
                // Pop right operand (b)
                let b = stack[stack.len() - 1];
                stack = std::array::slice(stack, 0, stack.len() - 1);

                // Pop left operand (a)
                let a = stack[stack.len() - 1];
                stack = std::array::slice(stack, 0, stack.len() - 1);

                // Push result (a + b)
                let result = a + b;
                stack = std::array::append(stack, [result]);
            }
            Token::Sub => {
                // Pop right operand (b)
                let b = stack[stack.len() - 1];
                stack = std::array::slice(stack, 0, stack.len() - 1);

                // Pop left operand (a)
                let a = stack[stack.len() - 1];
                stack = std::array::slice(stack, 0, stack.len() - 1);

                // Push result (a - b)
                let result = a - b;
                stack = std::array::append(stack, [result]);
            }
            Token::Mul => {
                // Pop right operand (b)
                let b = stack[stack.len() - 1];
                stack = std::array::slice(stack, 0, stack.len() - 1);

                // Pop left operand (a)
                let a = stack[stack.len() - 1];
                stack = std::array::slice(stack, 0, stack.len() - 1);

                // Push result (a * b)
                let result = a * b;
                stack = std::array::append(stack, [result]);
            }
        }
    }

    // The result is the single value left on the stack.
    // Since inputs are guaranteed well-formed, the stack must contain exactly one element.
    stack[0]
}

fn main() -> Int {
    // Example 1: 2 3 + -> 5
    let tokens1: [Token; 7] = [
        Token::Num { value: 2 },
        Token::Num { value: 3 },
        Token::Add,
        Token::Num { value: 1 },
        Token::Num { value: 1 },
        Token::Num { value: 1 },
        Token::Num { value: 1 },
    ];
    let result1 = eval_rpn(tokens1);

    // Example 2: 10 2 3 * - -> 10 - (2*3) = 4
    let tokens2: [Token; 7] = [
        Token::Num { value: 10 },
        Token::Num { value: 2 },
        Token::Num { value: 3 },
        Token::Mul,
        Token::Sub,
        Token::Add,
        Token::Add,
    ];
    let result2 = eval_rpn(tokens2);

    // We return the result of the first example as the exit status.
    result1
}

