module rle_encoder;

import std::str;

/// Returns the run-length encoding of the input string.
/// Each maximal run of one repeated byte becomes that byte followed by the run's length in decimal.
/// "aaabcc" becomes "a3b1c2". The empty string encodes to the empty string.
pub fn rle(in s: Str) -> String {
    if s.len() == 0 {
        return String::builder().push("").build();
    }

    let mut result_builder = String::builder();
    let bytes = std::str::split(s, ""); // Treat string as sequence of characters/bytes for iteration

    let mut current_byte = std::str::index_of_byte(s, 0);
    let mut count = 0;
    let mut current_index = 0;

    while current_index < s.len() {
        let start_char = std::str::index_of_byte(s, current_index);
        if start_char.is_none() {
            break; // Should not happen if s is valid
        }
        let byte_val = start_char.unwrap();

        let mut run_count = 1;
        let mut next_index = current_index + 1;

        while next_index < s.len() {
            let next_char = std::str::index_of_byte(s, next_index);
            if next_char.is_none() {
                break;
            }
            let next_byte_val = next_char.unwrap();

            if next_byte_val == byte_val {
                run_count = run_count + 1;
                next_index = next_index + 1;
            } else {
                break;
            }
        }

        // Append the character and the count
        result_builder.push(std::str::to_string(byte_val));
        result_builder.push_int(run_count);

        // Move to the next distinct character
        current_index = next_index;
    }

    result_builder.build()
}

spec rle {
    then rle("aaabcc") == "a3b1c2";
    then rle("aaaaa") == "a5";
    then rle("abcde") == "a1b1c1d1e1";
    then rle("a") == "a1";
    then rle("") == "";
    then rle("zzzyyxx") == "z3y2x2";
}

