/// Returns the quotient a / b, or None if b is 0.
pub fn safe_div(take a: Int, take b: Int) -> Option[Int] {
    if b == 0 {
        None
    } else {
        Some { value: a / b }
    }
}

/// Calls safe_div and returns the fallback if the result is None.
pub fn div_or(take a: Int, take b: Int, take fallback: Int) -> Int {
    std::core::unwrap_or(safe_div(a, b), fallback)
}

