/// Calculates the greatest common divisor of two non-negative integers using the Euclidean algorithm.
pub fn gcd(take a: Int, take b: Int) -> Int {
    var x = a;
    var y = b;
    while y != 0 {
        var temp = y;
        y = x % y;
        x = temp;
    }
    x
}

