/// Checks if a string reads the same byte-for-byte forwards and backwards.
pub fn is_palindrome(in s: Str) -> Bool {
    if s.len() == 0 {
        return true;
    }

    let bytes = std::str::bytes_of_str(in s);
    let len = std::array::len(bytes);

    // We only need to check up to the middle element (inclusive for odd length)
    for i in 0..len / 2 {
        // Compare byte at index i with byte at index len - 1 - i
        let byte_forward = std::array::select(bytes, i);
        let byte_backward = std::array::select(bytes, len - 1 - i);

        if byte_forward != byte_backward {
            return false;
        }
    }
    true
}

