module app;

import std::str;
import std::array;

/// Sums comma-separated non-negative decimal integers.
/// Example: "10,20,3" -> 33
/// Empty string "" -> 0
pub fn sum_csv(s: Str) -> Int {
    if std::str::is_empty(s) {
        return 0;
    }

    let parts: Array[String] = std::str::split(s, ",");

    let mut sum: Int = 0;

    for part in parts {
        // std::str::parse_int returns Result[Int, Str].
        match std::str::parse_int(part) {
            Ok(n) => {
                sum = sum + n;
            },
            Err(_) => {
                // Assuming valid input as per prompt, error path is ignored.
            }
        }
    }
    sum
}

