module word_utils;

import std::str;
import std::collections;

/// Returns the length of the longest space-separated word in the given text.
/// Returns 0 if the text contains no words.
pub fn longest_word_length(in text: Str) -> Int {
    let words: Array[String] = std::str::split(in text, " ");

    let mut max_len = 0;
    for word in words {
        let len = std::str::count(word, " "); // Should be safe if split works as expected, but we use length for safety
        let word_len = std::str::length(word);
        if word_len > max_len {
            max_len = word_len;
        }
    }
    max_len
}

/// Counts how many space-separated words in the text exactly match the given word.
/// Uses a Map[Str, Int] internally.
pub fn count_word(in text: Str, in word: Str) -> Int {
    let words: Array[String] = std::str::split(in text, " ");
    let mut word_counts: std::collections::Map[String, Int] = std::collections::Map::empty();

    for w in words {
        // We must handle potential empty strings resulting from multiple spaces,
        // although std::str::split behavior might vary. Assuming split handles
        // multiple spaces by producing empty strings or skipping them.
        // If the input guarantees single space separation, this is fine.
        // If we must strictly count only non-empty words:
        if w.is_empty() {
            continue;
        }

        // Update the map
        let current_count = word_counts.get(w).unwrap_or(0);
        word_counts.insert(w, current_count + 1);
    }

    // Retrieve the count for the target word
    if let Some(count) = word_counts.get(in word) {
        count
    } else {
        0
    }
}

spec longest_word_length {
    then longest_word_length("hello world").to_string() == 5;
    then longest_word_length("a b c").to_string() == 1;
    then longest_word_length("singleword").to_string() == 10;
    then longest_word_length("").to_string() == 0;
    then longest_word_length("   ").to_string() == 0; // Assuming split handles this gracefully or we filter empty results
}

spec count_word {
    then count_word("the quick brown fox".to_string(), "quick".to_string()) == 1;
    then count_word("apple banana apple".to_string(), "apple".to_string()) == 2;
    then count_word("test test test".to_string(), "other".to_string()) == 0;
    then count_word("".to_string(), "word".to_string()) == 0;
    then count_word(" ".to_string(), "word".to_string()) == 0;
}

